# We avoid built-in libraries for shortcuts, as in real interviews.

class TreeMap:
    # Simple BST map supporting find predecessor/successor
    def __init__(self):
        self.data = {}

    def insert(self, k, v):
        self.data[k] = v

    def keys(self):
        return sorted(self.data.keys())

    def predecessor(self, k):
        # Find largest key < k
        keys = self.keys()
        pred = None
        for x in keys:
            if x < k:
                pred = x
            else:
                break
        return pred

    def successor(self, k):
        # Find smallest key > k
        keys = self.keys()
        for x in keys:
            if x > k:
                return x
        return None

    def get(self, k):
        return self.data.get(k, 0)


def maxDepthBST(order):
    tm = TreeMap()
    n = len(order)
    tm.insert(float('-inf'), 0)  # Handle no predecessor edge case
    tm.insert(float('inf'), 0)   # Handle no successor edge case

    root = order[0]
    tm.insert(root, 1)
    max_depth = 1

    for v in order[1:]:
        pred = tm.predecessor(v)
        succ = tm.successor(v)
        depth = 1 + max(tm.get(pred), tm.get(succ))
        tm.insert(v, depth)
        max_depth = max(max_depth, depth)

    return max_depth

